<template>
<section class="technical-quotes">
<button type="button" @click="open=true;page=1;search()" :disabled="disabled">Buscar proforma del sistema</button>
<b-modal v-model="open" title="Buscar proforma del sistema" size="xl" centered hide-footer modal-class="technical-quotes-modal" body-class="technical-quotes-body" :no-close-on-backdrop="loading">
<form class="technical-quotes-search" @submit.prevent="page=1;search()"><input v-model="query" placeholder="Buscar por cliente o proforma" aria-label="Buscar por cliente o proforma"><label>Desde<input v-model="from" type="date" required aria-label="Desde"></label><label>Hasta<input v-model="to" type="date" required aria-label="Hasta"></label><button type="submit" :disabled="loading">Buscar</button></form>
<p v-if="error" role="alert">{{error}}</p><p v-if="loading" role="status">Cargando...</p>
<div class="technical-quotes-table"><table><thead><tr><th>Proforma</th><th>Cliente</th><th>Documento</th><th>Fecha</th><th>Total</th><th>Usuario</th><th>Productos</th></tr></thead><tbody><tr v-for="quote in quotes" :key="quote.IdProforma" :class="{selected:selected &amp;&amp; selected.IdProforma===quote.IdProforma}"><td>{{quote.Anio}}-{{quote.Numero}}</td><td>{{quote.Cliente}}</td><td>{{quote.DniRuc}}</td><td>{{quote.FechaReg}}</td><td>{{quote.Total}}</td><td>{{quote.UsuarioReg}}</td><td><button type="button" :disabled="loading" @click="load(quote)" :aria-label="'Seleccionar proforma '+quote.Anio+'-'+quote.Numero">Seleccionar</button></td></tr><tr v-if="!loading &amp;&amp; !quotes.length"><td colspan="7">No se encontraron proformas.</td></tr></tbody></table></div>
<nav class="technical-quotes-pages" aria-label="Paginacion de proformas"><span>25 proformas por página · {{total}} resultados</span><button type="button" :disabled="page===1 || loading" @click="page--;search()">Anterior</button><span>Página {{page}}</span><button type="button" :disabled="page*25>=total || loading" @click="page++;search()">Siguiente</button></nav>
<section v-if="selected" class="technical-quotes-products"><h3>Productos de la proforma {{selected.Anio}}-{{selected.Numero}}</h3><label v-for="(product,i) in products" :key="i" class="technical-quote-product"><input type="checkbox" v-model="chosen" :value="i">{{product.Producto}}<small>{{product.ProductoModelo}} - Cantidad: {{product.Cantidad}}</small></label><p v-if="!products.length">La proforma no tiene productos disponibles.</p></section>
<footer class="technical-quotes-footer"><button type="button" @click="open=false">Cerrar buscador</button><button type="button" class="technical-quotes-import" :disabled="!selected || !chosen.length || loading" @click="use">Cargar productos para comparar</button></footer>
</b-modal></section></template>
<script>
import config from '@/store/config.js'
function initialDates(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(p=>p.type===t).value;const end=get('year')+'-'+get('month')+'-'+get('day');const d=new Date(end+'T12:00:00Z');const day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-1);const max=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,max));return {from:d.toISOString().slice(0,10),to:end}}
export default {props:{disabled:Boolean},data(){return {...initialDates(),total:0,open:false,query:'',page:1,quotes:[],selected:null,products:[],chosen:[],loading:false,error:''}},methods:{async get(route){const response=await this.axios.get(config.API+route);if(!Array.isArray(response.data))throw Error('No se pudieron leer los datos de la proforma.');return response.data},async search(){this.loading=true;this.error='';try{if(!this.from||!this.to||this.from>this.to)throw Error('Revisa el rango de fechas.');const cfg=await fetch('/api/index.php/ali/config',{credentials:'same-origin'}).then(r=>r.json());const response=await fetch('/api/index.php/ali/tecnico',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':cfg.csrf},body:JSON.stringify({action:'quote_history',from:this.from,to:this.to,query:this.query,page:this.page})});const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo leer el historial.');this.quotes=result.quotes;this.total=result.total}catch(e){this.error=e.message}finally{this.loading=false}},async load(quote){this.loading=true;this.error='';try{this.products=await this.get('proformas/detalle?idProforma='+encodeURIComponent(quote.IdProforma));this.selected=quote;this.chosen=this.products.map((p,i)=>i)}catch(e){this.error=e.message}finally{this.loading=false}},use(){const rows=this.chosen.map(i=>this.products[i]);const text='Proforma '+this.selected.Anio+'-'+this.selected.Numero+' (oferta declarada, verificar especificaciones):\n'+rows.map((p,i)=>(i+1)+'. '+p.Producto+' | Modelo: '+(p.ProductoModelo||'No informado')+' | Cantidad: '+p.Cantidad+'\n'+(p.Descripcion||p.ProductoDesc||'Sin características registradas')).join('\n\n');if(text.length>5500){this.error='Selecciona menos productos para evaluar sus características completas.';return;}this.$emit('select',{text,quote:this.selected,products:rows});this.open=false}}}
</script>
<style>
.technical-quotes{margin:16px 0}.technical-quotes-modal .modal-dialog{max-width:1200px;width:calc(100% - 24px)}.technical-quotes-modal .modal-content{border-radius:18px;overflow:hidden}.technical-quotes-modal .modal-header{background:#163d54;color:white;padding:16px 20px}.technical-quotes-modal .close{color:white;opacity:1}.technical-quotes-body{max-height:80vh;overflow:auto;padding:20px}.technical-quotes-search{display:flex;flex-wrap:wrap;align-items:flex-end;gap:10px;margin-bottom:16px}.technical-quotes-search>input{flex:1 1 220px;}.technical-quotes-search label{font-size:12px;margin:0;display:flex;flex-direction:column;gap:5px}.technical-quotes-search input{flex:1;min-width:0;border:1px solid #cbd8ef;border-radius:10px;padding:12px}.technical-quotes-modal button{border:1px solid #cbd8ef;border-radius:9px;background:white;color:#365782;padding:10px 15px;cursor:pointer}.technical-quotes-modal button:disabled{opacity:.45;cursor:default}.technical-quotes-table{overflow:auto;max-height:45vh;border:1px solid #e1e8f2;border-radius:10px}.technical-quotes-table table{width:100%;border-collapse:collapse;min-width:760px}.technical-quotes-table th{position:sticky;top:0;background:#163d54;color:white;text-align:left;padding:12px}.technical-quotes-table td{padding:10px 12px;border-bottom:1px solid #e1e8f2}.technical-quotes-table tr:nth-child(even){background:#f6f9fc}.technical-quotes-table tr.selected{background:#e8e5ff}.technical-quotes-pages{display:flex;gap:12px;align-items:center;justify-content:flex-end;flex-wrap:wrap;margin:14px 0;font-size:13px}.technical-quotes-pages>span:first-child{margin-right:auto}.technical-quotes-products{border-top:1px solid #dce5f2;padding-top:14px}.technical-quotes-products h3{font-size:18px}.technical-quote-product{display:block;padding:10px;border-bottom:1px solid #e5eaf5}.technical-quote-product input{width:auto;margin-right:10px}.technical-quote-product small{display:block;margin-left:24px}.technical-quotes-footer{position:sticky;bottom:-20px;background:white;display:flex;justify-content:flex-end;gap:10px;padding:16px 0 0;margin-top:16px;border-top:1px solid #dce5f2}.technical-quotes-footer .technical-quotes-import{background:#5145ad;color:white;border-color:#5145ad}@media(max-width:600px){.technical-quotes-body{padding:12px}.technical-quotes-footer{bottom:-12px}.technical-quotes-footer button{padding:10px;font-size:13px}.technical-quotes-pages{gap:8px}}
</style>
